<script setup>import {ref,onMounted} from 'vue';import {useData} from '../stores/data';import Notice from '../components/Notice.vue';const store=useData(),form=ref({id:'',name:''}),message=ref(''),error=ref(''),busy=ref(false);onMounted(()=>store.refresh().catch(e=>error.value=e.message));async function add(){busy.value=true;error.value='';message.value='';try{await store.request('/courses',{method:'POST',body:JSON.stringify(form.value)});form.value={id:'',name:''};await store.refresh();message.value='Course created successfully'}catch(e){error.value=e.message}finally{busy.value=false}}async function remove(c){if(!confirm('Delete '+c.id+' and all its enrollments?'))return;error.value='';message.value='';try{await store.request('/courses/'+c._id,{method:'DELETE'});await store.refresh();message.value='Course deleted'}catch(e){error.value=e.message}}</script><template><div class="eyebrow">ACADEMIC CATALOG</div><h1>Courses</h1><p class="subtitle">Create and organize courses.</p><div class="stats"><div class="stat"><span>Active courses</span><strong>{{store.courses.length}}</strong></div></div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>Create a course</h2></div><form @submit.prevent="add" class="form"><label>Course ID<input v-model.trim="form.id" placeholder="e.g. CIS 3339" required></label><label>Course name<input v-model.trim="form.name" placeholder="e.g. Enterprise Applications Development" required></label><button class="primary" :disabled="busy">{{busy?'Saving…':'+ Add course'}}</button></form><Notice :message="error" type="error"/><Notice :message="message"/></section><section class="panel"><div class="panel-heading"><h2>Course catalog</h2></div><div v-if="store.loading" class="empty">Loading courses…</div><div v-else-if="!store.courses.length" class="empty">No courses yet.</div><div v-for="c in store.courses" :key="c._id" class="record"><div class="avatar">▤</div><div class="record-body"><strong>{{c.id}}</strong><span>{{c.name}}</span></div><button class="danger" @click="remove(c)">Delete</button></div></section></div></template>